&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Minimum&amp;nbsp;10&amp;nbsp;years of related work experience, including significant experience&amp;nbsp;maintaining&amp;nbsp;complex multi-year financial models&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;335572071&amp;quot;:0,&amp;quot;335572072&amp;quot;:0,&amp;quot;335572073&amp;quot;:4278190080,&amp;quot;335572075&amp;quot;:0,&amp;quot;335572076&amp;quot;:0,&amp;quot;335572077&amp;quot;:4278190080,&amp;quot;335572079&amp;quot;:0,&amp;quot;335572080&amp;quot;:0,&amp;quot;335572081&amp;quot;:4278190080,&amp;quot;335572083&amp;quot;:0,&amp;quot;335572084&amp;quot;:0,&amp;quot;335572085&amp;quot;:4278190080,&amp;quot;335572087&amp;quot;:0,&amp;quot;335572088&amp;quot;:0,&amp;quot;335572089&amp;quot;:4278190080,&amp;quot;469789798&amp;quot;:&amp;quot;nil&amp;quot;,&amp;quot;469789802&amp;quot;:&amp;quot;nil&amp;quot;,&amp;quot;469789806&amp;quot;:&amp;quot;nil&amp;quot;,&amp;quot;469789810&amp;quot;:&amp;quot;nil&amp;quot;,&amp;quot;469789814&amp;quot;:&amp;quot;nil&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Knowledge of fundraising channel analysis&amp;nbsp;and/or experience supporting fundraising departments&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
