&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Electronic documentation&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
